public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }
    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();
    int commonLetters = 0;
    int lengthSum = word1.length() + word2.length();
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) != -1) {
            commonLetters++;
            word2 = word2.replaceFirst("" + c, "");
        }
    }
    if (lengthSum == 0) {
        return "appx(?, ?) = 0";
    }
    int gcd = gcd(commonLetters, lengthSum);
    return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + (commonLetters / gcd) + "/" + (lengthSum / gcd);
}

