public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i)th digit which is greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the above found smallest digit with digits[i]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i)th digit in ascending order
    Arrays.sort(digits, i + 1, length);

    // Convert the array back to an integer
    long val = Long.parseLong(new String(digits));

    // Check if the result is non-negative and greater than n
    return (val > Integer.MAX_VALUE || val <= n) ? -1 : (int) val;
}

